import{c as n,Q as a,j as s,m as i}from"./chunks/framework.BPKcPtvA.js";const r="/screenshots/library-detail.png",o="/screenshots/detail-file-info.png",l="/screenshots/detail-version.png",e="/screenshots/detail-folder-copy.png",d="/screenshots/detail-unity-multiselect.png",k=JSON.parse('{"title":"商品詳細画面","description":"","frontmatter":{},"headers":[],"relativePath":"guide/library-detail.md","filePath":"guide/library-detail.md","lastUpdated":1786391114000}'),p={name:"guide/library-detail.md"};function g(c,t,h,u,b,m){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="商品詳細画面" tabindex="-1">商品詳細画面 <a class="header-anchor" href="#商品詳細画面" aria-label="Permalink to &quot;商品詳細画面&quot;">​</a></h1><p>ライブラリのカードをクリックすると開く、アイテム 1 つ分の詳細画面です。 ファイル一覧 / 個別ダウンロード / 関連アイテム / バージョン履歴などをこの画面でまとめて見れます。</p><p><img src="'+r+`" alt="商品詳細画面 — パンくず、左にファイル一覧、右に説明と関連アイテム"></p><blockquote><p>画面内の商品名・ショップ名はデモ用の架空データです。</p></blockquote><h2 id="構成" tabindex="-1">構成 <a class="header-anchor" href="#構成" aria-label="Permalink to &quot;構成&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ← ライブラリ › ショップ名 › 商品名                       │ ← パンくず</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ ┌────┐  商品名                                          │</span></span>
<span class="line"><span>│ │サムネ│  ◯ ショップ名                                    │ ← ヘッダ</span></span>
<span class="line"><span>│ └────┘  [カテゴリ] [タグ] [価格] [購入日]               │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ ┌───────────────────┐ ┌────────────────────────────────┐│</span></span>
<span class="line"><span>│ │📁 フォルダー(N) 📦 Unity Package(N)                  ││ ← タブ</span></span>
<span class="line"><span>│ │ ┌─────────────┐   │ │ ファイル情報パネル              ││</span></span>
<span class="line"><span>│ │ │ファイル一覧  │   │ │ - 説明 / メモ                  ││</span></span>
<span class="line"><span>│ │ │             │   │ │ - バージョン履歴                ││</span></span>
<span class="line"><span>│ │ │             │   │ │ - 関連アイテム                  ││</span></span>
<span class="line"><span>│ │ │             │   │ │ - フォルダ内容の一覧            ││</span></span>
<span class="line"><span>│ │ └─────────────┘   │ │                                ││</span></span>
<span class="line"><span>│ └───────────────────┘ └────────────────────────────────┘│</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="ファイル一覧-📁-フォルダー-タブ" tabindex="-1">ファイル一覧 (📁 フォルダー タブ) <a class="header-anchor" href="#ファイル一覧-📁-フォルダー-タブ" aria-label="Permalink to &quot;ファイル一覧 (📁 フォルダー タブ)&quot;">​</a></h2><p>このアイテムでダウンロードできる全ファイルが並びます。</p><h3 id="デフォルトの並び順" tabindex="-1">デフォルトの並び順 <a class="header-anchor" href="#デフォルトの並び順" aria-label="Permalink to &quot;デフォルトの並び順&quot;">​</a></h3><ol><li><strong>現行版が上、旧版が下</strong> — 同じベース名 (バージョン表記を除いた共通部分) で <code>_v1</code>, <code>_v2</code>, <code>_v3</code> のようにバージョン違いがある場合、最新版だけが上のグループ、 旧版は下のグループに集まります。</li><li>それぞれのグループ内は <strong>ファイル名の昇順</strong> (<code>v1, v2, v10</code> が正しい数値順になる 自然な並び)。</li></ol><p>設定で並び順を「名前順」(現行 / 旧の区別をなくした単純な名前順) や 「取得時の順序」(保存されている並びをそのまま使用) に切り替えることもできます。</p><h3 id="行の状態" tabindex="-1">行の状態 <a class="header-anchor" href="#行の状態" aria-label="Permalink to &quot;行の状態&quot;">​</a></h3><ul><li>アイコン (📦 / 🎨 / 🖼️ / 🧊 / 🎵 / 🎬 / 📕 / 📁): 拡張子ごと</li><li><code>旧</code> バッジ: アイコン右下、バージョン系列の最新でないファイル</li><li>進捗バー: ダウンロード中</li><li>色: 緑 = 完了 / アクセント色 = ダウンロード中 / 暗く表示 = 未ダウンロード / 赤 = 失敗</li><li>右クリックで個別ダウンロード / 削除 / プレビュー / ドラッグ&amp;ドロップ など</li></ul><h3 id="クリックで右側パネル更新" tabindex="-1">クリックで右側パネル更新 <a class="header-anchor" href="#クリックで右側パネル更新" aria-label="Permalink to &quot;クリックで右側パネル更新&quot;">​</a></h3><p>行をクリックすると、右側に「このファイルの情報」が表示されます:</p><ul><li>取得日 / サイズ / 保存先のパス</li><li><strong>URL 期限</strong> — まだダウンロードが完了しておらず、ダウンロード用 URL に期限がある ファイルで「URL 期限: 日時」を表示 (期限を過ぎても再ダウンロード時に自動で取り直します)</li><li>進捗バー (ダウンロード中)</li><li>ファイル名の右にあるフォルダアイコン (ダウンロード済みならエクスプローラーで表示)</li><li><strong>フォルダ内容の一覧</strong> (.zip を展開済みの場合、中身をツリー表示)</li><li><strong>バージョン履歴</strong> (同じベース名の系列の一覧、現行 / 旧のバッジ)</li><li><strong>関連アイテム</strong> (同じショップ / 同じタグの他アイテム)</li><li><strong>🔁 同じ中身のファイル</strong> (重複スキャン済みで、同じ内容のファイルが他にもある場合に「🔁 同一ファイル N 件」として表示。クリックで相互に移動できます。スキャンは <a href="/guide/settings#重複ファイルのスキャン">設定 &gt; 重複ファイルのスキャン</a> から)</li></ul><p><img src="`+o+'" alt="ファイル情報パネル — 取得日 / サイズ / 保存先のパス + 関連アイテム"></p><p>同じベース名でバージョン違い (<code>_v1</code> / <code>_v2</code> …) があるファイルを選ぶと、右側に <strong>バージョン履歴</strong> が出て、現行 (現在) と旧版の系列をまとめて確認できます。</p><p><img src="'+l+'" alt="バージョン履歴 — 現在 / 旧 バッジ付きのバージョン系列"></p><h3 id="フォルダ内容の操作" tabindex="-1">フォルダ内容の操作 <a class="header-anchor" href="#フォルダ内容の操作" aria-label="Permalink to &quot;フォルダ内容の操作&quot;">​</a></h3><p>展開済み ZIP を選んだときに右側へ出る <strong>フォルダ内容</strong> の各行 (ファイル / フォルダ) は、そのまま操作できます:</p><ul><li><strong>ダブルクリック</strong> — エクスプローラーで表示</li><li><strong>ドラッグ</strong> — 外部アプリ (エクスプローラー / Unity / 画像ビューア など) へドロップ</li><li><strong>右クリックメニュー</strong>: <ul><li><strong>👁 プレビュー</strong> (画像 / テキストのとき)</li><li><strong>📂 エクスプローラーで開く</strong></li><li><strong>📋 ファイル名をコピー / 📋 パスをコピー</strong></li><li><strong>📁 フォルダ構成を保ってコピー</strong> / <strong>📄 平坦にコピー</strong> — 選んだファイルを 別のフォルダへコピーします。前者は元のフォルダ階層のまま、後者は中身を 1 階層に平らにまとめます。どちらもコピー先に同じ名前がある場合は、 <code>(2)</code> などを付けた別名で保存します</li><li>行が <code>.unitypackage</code> のときは <strong>🎯 Unity に取り込み</strong> も出ます</li></ul></li></ul><p><img src="'+e+'" alt="フォルダ内容の右クリックメニュー — 複数選択して フォルダ構成を保ってコピー / 平坦にコピー など"></p><h2 id="📦-unity-package-タブ" tabindex="-1">📦 Unity Package タブ <a class="header-anchor" href="#📦-unity-package-タブ" aria-label="Permalink to &quot;📦 Unity Package タブ&quot;">​</a></h2><p><code>.unitypackage</code> だけを抜き出した一覧です。展開済みの ZIP の中も再帰的に探して 拾います。</p><h3 id="unity-に取り込む-windows-のみ" tabindex="-1">Unity に取り込む (Windows のみ) <a class="header-anchor" href="#unity-に取り込む-windows-のみ" aria-label="Permalink to &quot;Unity に取り込む (Windows のみ)&quot;">​</a></h3><p>行を選ぶと右側に出る <strong>「🎯 Unity に取り込み」</strong> ボタン、または行を右クリックした メニューの同じ項目から、起動中の Unity に渡せます。</p><ul><li>起動中の Unity を自動で検出します</li><li>起動していないときは「Unity が起動していません」と表示されます</li><li><strong>複数の Unity を起動している場合は、どのプロジェクトに渡すかを選ぶ一覧が出ます</strong></li><li>macOS など Windows 以外では使えません (ボタンは押せない状態で表示)</li></ul><h3 id="行の右クリックメニュー" tabindex="-1">行の右クリックメニュー <a class="header-anchor" href="#行の右クリックメニュー" aria-label="Permalink to &quot;行の右クリックメニュー&quot;">​</a></h3><p>各 <code>.unitypackage</code> 行を右クリックすると、その場で操作できます:</p><ul><li><strong>🎯 Unity に取り込み</strong></li><li><strong>📂 エクスプローラーで開く</strong></li><li><strong>📋 ファイル名をコピー / 📋 パスをコピー</strong></li><li><strong>📤 全体をエクスポート</strong> / <strong>📤 全体をエクスポート (メタデータを含む)</strong> — パッケージの中身を丸ごと、選んだフォルダに Unity のパス構成のままエクスポートします</li></ul><h3 id="中身の確認と部分エクスポート" tabindex="-1">中身の確認と部分エクスポート <a class="header-anchor" href="#中身の確認と部分エクスポート" aria-label="Permalink to &quot;中身の確認と部分エクスポート&quot;">​</a></h3><p>パッケージを選ぶと右側に <strong>中身 (Unity 内のパス)</strong> が一覧表示されます。各行は ドラッグして Unity などにドロップできるほか、右クリックで個別のアセット / フォルダだけを操作できます:</p><ul><li><strong>📤 エクスポート</strong> / <strong>📤 エクスポート (メタデータを含む)</strong> — そのアセット / フォルダだけを取り出します</li><li><strong>📋 ファイル名をコピー</strong> — その行の名前をコピーします</li><li><strong>📋 Unity内パスをコピー</strong> — <code>Assets/…</code> から始まる Unity 内のパスをコピーします</li></ul><h3 id="複数まとめて-unity-に取り込み" tabindex="-1">複数まとめて Unity に取り込み <a class="header-anchor" href="#複数まとめて-unity-に取り込み" aria-label="Permalink to &quot;複数まとめて Unity に取り込み&quot;">​</a></h3><p>行を <strong>Shift / Ctrl + クリック</strong> で複数選んでから右クリックすると、 <strong>「🎯 選択 N 件をまとめて import」</strong> が出ます。選んだパッケージを 1 つに結合して 渡すので、<strong>Unity の取り込みダイアログは 1 回</strong>で全アセットが出ます (1 個ずつ渡すと 2 件目以降が取りこぼされるため、まとめる方式です)。</p><p><img src="'+d+'" alt="Unity Package タブで複数選択 — 右クリックの「選択 N 件をまとめて import」"></p><ul><li>合計サイズが大きいときは、結合のおおよその所要時間を添えた確認が出ます</li><li>結合中は進捗 (○/○) が出て、<strong>キャンセル</strong>もできます</li><li>結合中は <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> からも進み具合の確認と中止ができます</li><li>「結合せずに 1 個ずつ Unity へドラッグ&amp;ドロップ」(取り込みダイアログが件数分 開く方式) も使えます — 確認のメッセージで案内されます</li></ul><h2 id="リストの複数選択" tabindex="-1">リストの複数選択 <a class="header-anchor" href="#リストの複数選択" aria-label="Permalink to &quot;リストの複数選択&quot;">​</a></h2><p><strong>左側のファイル一覧</strong>・<strong>フォルダ内容</strong>・<strong>Unity Package タブ</strong> のリストは、 複数まとめて選べます。</p><table tabindex="0"><thead><tr><th>操作</th><th>動作</th></tr></thead><tbody><tr><td><strong>クリック</strong></td><td>その 1 件だけ選択</td></tr><tr><td><strong>Ctrl + クリック</strong> (Mac は ⌘)</td><td>クリックした行を選択に追加 / 解除</td></tr><tr><td><strong>Shift + クリック</strong></td><td>直前に選んだ行からクリックした行までをまとめて選択</td></tr></tbody></table><p>選んだ行はまとめて次のことができます:</p><ul><li><strong>まとめてドラッグ&amp;ドロップ</strong> — 選択中の 1 件をドラッグすると、選択した 全ファイル/フォルダを一度に外部アプリへドロップします (ダウンロード済みの ものだけが対象です)</li><li><strong>右クリックメニューが選択全体に対象</strong> — 選択中の行を右クリックすると、 「選択 N 件を…」という形でまとめて実行できます (ファイル一覧なら選択分の ダウンロード / エクスプローラーで表示 / ファイル名・パスをコピー、 フォルダ内容ならコピー、<code>.unitypackage</code> ならまとめて import)</li></ul><blockquote><p>選択していない行を右クリックした場合は、その 1 件だけが対象になります。 ファイル一覧では、修飾キーなしのクリックは右側にそのファイルの 詳細を表示します。</p></blockquote><h2 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー操作</th><th>動作</th></tr></thead><tbody><tr><td><strong>マウスの戻るボタン</strong></td><td>履歴の 1 つ前へ戻る</td></tr><tr><td><strong>マウスの進むボタン</strong></td><td>戻った先から再度進む</td></tr><tr><td><strong>Alt + ←</strong></td><td>履歴の 1 つ前へ戻る</td></tr><tr><td><strong>Alt + →</strong></td><td>進む</td></tr><tr><td><strong>Esc</strong></td><td>パネル内のダイアログ / プレビューを閉じる (開いていなければ履歴の 1 つ前へ戻る)</td></tr><tr><td><strong>↑ / ↓</strong></td><td>ファイル一覧のカーソルを上下に移動</td></tr><tr><td><strong>Enter</strong></td><td>カーソル位置のファイルを選択 (右側に情報を表示)</td></tr><tr><td><strong>Shift + ↑ / ↓</strong></td><td>カーソルを動かしながら範囲選択</td></tr><tr><td><strong>Ctrl + A</strong></td><td>リストのファイルを全て選択</td></tr><tr><td><strong>← / →</strong></td><td>「📁 フォルダー」「📦 Unity Package」タブを切り替え</td></tr><tr><td><strong>アプリケーションキー (メニューキー)</strong></td><td>カーソル行の右クリックメニューを開く</td></tr></tbody></table><p>矢印キー / Enter などの詳細画面のキーは <a href="/guide/settings#キーボードショートカット">設定 &gt; キーボードショートカット</a> から 好きなキーに変更できます。</p><h2 id="メモ-カテゴリ" tabindex="-1">メモ / カテゴリ <a class="header-anchor" href="#メモ-カテゴリ" aria-label="Permalink to &quot;メモ / カテゴリ&quot;">​</a></h2><ul><li>詳細ヘッダ右側のメモ編集アイコンから、1 アイテムにつき 1 つのメモを自由入力できます</li><li>詳細の「🏷️ 編集」またはカードの右クリックメニューの 「🏷️ カテゴリを編集」から、BOOTH 公式カテゴリを 1 つ選び、 カスタムカテゴリを複数付与できます</li></ul><p>メモとこれらのカテゴリ編集は BOOTH には送らず、手元のデータとして保存します。 ライブラリの絞り込みや、カーソルを乗せたときのポップアップで参照できます。</p><p>商品説明やメモの中に書かれた <code>http(s)://…</code> の URL は自動でリンクになり、 クリックするとブラウザで開きます。</p><h2 id="アクション" tabindex="-1">アクション <a class="header-anchor" href="#アクション" aria-label="Permalink to &quot;アクション&quot;">​</a></h2><ul><li><strong>商品名の横のコピーアイコン</strong>: 商品名をクリップボードにコピーします</li><li><strong>商品名</strong> (BOOTH の商品): ブラウザで <code>https://booth.pm/items/{id}</code> を開きます</li><li><strong>ショップ名</strong> (ショップ情報がある場合): ブラウザでそのショップのページを開きます</li><li><strong>ショップ名の横の情報ボタン (ℹ)</strong> (ショップ情報がある場合): <strong>アプリ内</strong>で「このショップの (ライブラリ内) アイテム一覧」を開きます (ブラウザは開かず、手元に持っている 同じショップのアイテムだけを一覧します)</li><li><strong>「↺」</strong> (BOOTH の商品): BOOTH から商品名 / 価格 / カテゴリなどを取り直します。 実行中は「商品情報を更新中…」、完了時は「商品情報を更新しました」、 失敗時は「商品情報の取得に失敗しました」と通知します</li></ul><p>ライブラリのカードを右クリックすると、次の操作を選べます。</p><ul><li><strong>「📥 未取得ファイルをダウンロード」</strong>: 失敗 / 期限切れ / 未取得のうち、 ダウンロード可能なファイルをまとめて予約する (非公開・対象外の旧版は除く)</li><li><strong>「📄 商品ページを開く」 / 「🏪 ショップを開く」</strong>: 各ページをブラウザで開きます</li><li><strong>「📦 アーカイブする」</strong>: ダウンロード済みファイルがある場合に表示します</li><li><strong>「🗑️ ゴミ箱に移動」</strong>: ファイル本体は残したまま「ゴミ箱」タグを立てます (デフォルトでは非表示)。30 日後に自動削除されます</li></ul><p>ライブラリのカードを <code>Shift</code> を押しながら右クリックすると、 「🔄 商品情報を更新」などの追加操作も表示します。</p><h2 id="アーカイブ" tabindex="-1">アーカイブ <a class="header-anchor" href="#アーカイブ" aria-label="Permalink to &quot;アーカイブ&quot;">​</a></h2><p>ライブラリのカードを右クリックして「📦 アーカイブする」を選ぶと、このアイテムの全ファイルを 1 つの ZIP にまとめ、元のファイルを削除します (保存先はアプリのデータフォルダ内)。</p><ul><li>ストレージの節約に</li><li>後から「アーカイブを解除」すると、現在設定されているダウンロード先フォルダへ 展開して復元します。アーカイブ後に保存先を変更していた場合も、新しい保存先へ戻ります</li><li>アーカイブ中はファイルを開く / ドラッグ&amp;ドロップ / Unity への取り込み ができなくなります</li></ul><h3 id="アーカイブ中の見え方" tabindex="-1">アーカイブ中の見え方 <a class="header-anchor" href="#アーカイブ中の見え方" aria-label="Permalink to &quot;アーカイブ中の見え方&quot;">​</a></h3><p>中身は ZIP の中に入っているので、詳細画面では操作できない項目が <strong>押せない状態 (グレーアウト)</strong> で表示されます。カーソルを乗せると 「アーカイブ内のため操作できません — 先に解除してください」と理由が出ます。</p><ul><li>ファイル情報パネルのフォルダアイコン、Unity Package の「🎯 Unity に取り込み」などは無効</li><li>右クリックメニューも取り込み / エクスプローラーで開く / パスをコピー / エクスポートが無効になります (<strong>ファイル名のコピーだけは可能</strong> — 名前は ディスク上のファイルが無くても分かるため)</li><li>フォルダ内容は「📦 アーカイブ内」と表示され、ダブルクリック / ドラッグ / 取り出しは できません</li></ul><p>まず「アーカイブを解除」で展開すれば、通常どおり操作できるようになります。</p><h2 id="更新あり通知" tabindex="-1">更新あり通知 <a class="header-anchor" href="#更新あり通知" aria-label="Permalink to &quot;更新あり通知&quot;">​</a></h2><p>購入済みのアイテムに <strong>出品者が新しいファイルを追加</strong> すると (BOOTH ライブラリの取得時に検出)、 カードに <code>📦 更新あり</code> タグが出ます。詳細画面を開くと自動で確認済みになり、タグが消えます。 通知ベルにも同時に届きます。</p>',65)])])}const q=n(p,[["render",g]]);export{k as __pageData,q as default};
